export async function drainNextQueueItem<T>(
  items: T[],
  run: (item: T) => Promise<void>,
  options?: DrainQueueItemOptions<T>,
): Promise<boolean> {
  const next = items.shift();
  if (!next) {
    return false;
  }
  try {
    await run(next);
  } catch (error) {
    if (options?.shouldRestoreOnError?.(next) ?? true) {
      items.unshift(next);
    } else {
      options?.onDiscard?.(next);
    }
    throw error;
  }
  return true;
}

