        endTalkTurn("response.done");
        return;
      }
      if (event.type === "error") {
        emitTalkEvent({
          type: "session.error",
          payload: { message: event.detail ?? "Realtime provider error" },
          final: true,
        });
      }
    },
    onReady: () => {
      emitTalkEvent({
        type: "session.ready",
        payload: { callId, providerCallId: callSid },
      });
    },
    onError: (error) => {
      console.error("[voice-call] realtime voice error:", error.message);
