export async function withRouteTabContext<T>(
  params: RouteWithTabParams<T>,
): Promise<T | undefined> {
  const profileCtx = resolveProfileContext(params.req, params.res, params.ctx);
  if (!profileCtx) {
    return undefined;
  }
  try {
    // Agent routes can address local-managed tabs through Playwright when per-tab WS discovery lags.
    const tab = await profileCtx.ensureTabAvailable(params.targetId, {
      allowPlaywrightFallback: true,
      signal: params.req.signal,
      timeoutMs: params.ctx.state().resolved.actionTimeoutMs,
    });
    if (params.enforceCurrentUrlAllowed) {
      await assertBrowserNavigationResultAllowed({
        url: tab.url,
        ...browserNavigationPolicyForProfile(params.ctx, profileCtx),
      });
    }
    return await params.run({
      profileCtx,
      tab,
      cdpUrl: profileCtx.profile.cdpUrl,
      resolveTabUrl: (fallbackUrl?: string) =>
        resolveSafeRouteTabUrl({
          ctx: params.ctx,
          profileCtx,
          targetId: tab.targetId,
          fallbackUrl,
          signal: params.req.signal,
          timeoutMs: params.ctx.state().resolved.actionTimeoutMs,
        }),
    });
  } catch (err) {
    handleRouteError(params.ctx, params.res, err);
    return undefined;
  }
}

export async function resolveSafeRouteTabUrl(params: {
  ctx: BrowserRouteContext;
  profileCtx: ProfileContext;
  targetId: string;
  fallbackUrl?: string;
  signal?: AbortSignal;
  timeoutMs?: number;
}): Promise<string | undefined> {
  let tabs: Array<{ targetId: string; url: string }>;
  try {
    tabs = await params.profileCtx.listTabs({ signal: params.signal, timeoutMs: params.timeoutMs });
  } catch {
    params.signal?.throwIfAborted();
    tabs = [];
  }
  const candidateUrl =
    tabs.find((tab) => tab.targetId === params.targetId)?.url ?? params.fallbackUrl;
  if (!candidateUrl) {
    return undefined;
  }
  try {
    await assertBrowserNavigationResultAllowed({
      url: candidateUrl,
      ...browserNavigationPolicyForProfile(params.ctx, params.profileCtx),
    });
    return candidateUrl;
  } catch {
    return undefined;
  }
}

async function collectChromeMcpSnapshotUrls(
  params: ChromeMcpSnapshotOperation,
): Promise<SnapshotUrlEntry[]> {
  const result = await evaluateChromeMcpScript({
    ...params,
    fn: `() => {
      const seen = new Set();
      const out = [];
      for (const anchor of Array.from(document.querySelectorAll("a[href]"))) {
        const href = anchor.href || "";
        if (!href || seen.has(href)) continue;
        const text = (anchor.innerText || anchor.textContent || anchor.getAttribute("aria-label") || "")
          .replace(/\\s+/g, " ")
          .trim()
          .slice(0, 121) || href;
        seen.add(href);
        out.push({ text, url: href });
        if (out.length >= 100) break;
      }
      return out;
    }`,
  }).catch(() => []);

async function clearChromeMcpOverlay(params: ChromeMcpSnapshotOperation): Promise<void> {
  await evaluateChromeMcpScript({
    ...params,
