/** Register file chooser and dialog hook endpoints on the browser control server. */
export function registerBrowserAgentActHookRoutes(
  app: BrowserRouteRegistrar,
  ctx: BrowserRouteContext,
) {
  app.post(
    "/hooks/file-chooser",
    asyncBrowserRoute(async (req, res) => {
      const body = readBody(req);
      const targetId = resolveTargetIdFromBody(body);
      const ref = toStringOrEmpty(body.ref) || undefined;
      const inputRef = toStringOrEmpty(body.inputRef) || undefined;
      const element = toStringOrEmpty(body.element) || undefined;
      const paths = toStringArray(body.paths) ?? [];
      let timeoutMs: number | undefined;
      try {
        timeoutMs = readRouteTimerTimeoutMs(body.timeoutMs);
      } catch (err) {
        return jsonError(res, 400, formatErrorMessage(err));
      }
      if (!paths.length) {
        return jsonError(res, 400, "paths are required");
      }

      await withRouteTabContext({
        req,
        res,
        ctx,
        targetId,
        run: async ({ profileCtx, cdpUrl, tab }) => {
          const resolvedResult = await resolveExistingUploadPaths({ requestedPaths: paths });
          if (!resolvedResult.ok) {
            res.status(400).json({ error: resolvedResult.error });
            return;
          }
          const resolvedPaths = resolvedResult.paths;

          if (getBrowserProfileCapabilities(profileCtx.profile).usesChromeMcp) {
            if (element) {
              return jsonError(res, 501, EXISTING_SESSION_LIMITS.hooks.uploadElement);
            }
            if (resolvedPaths.length !== 1) {
              return jsonError(res, 501, EXISTING_SESSION_LIMITS.hooks.uploadSingleFile);
            }
            const uid = inputRef || ref;
            if (!uid) {
              return jsonError(res, 501, EXISTING_SESSION_LIMITS.hooks.uploadRefRequired);
            }
            await uploadChromeMcpFile({
              profileName: profileCtx.profile.name,
              profile: profileCtx.profile,
              targetId: tab.targetId,
              uid,
              filePath: resolvedPaths[0] ?? "",
            });
            return res.json({ ok: true });
          }

          const pw = await requirePwAi(res, "file chooser hook");
          if (!pw) {
            return;
          }

          if (inputRef || element) {
            if (ref) {
              return jsonError(res, 400, "ref cannot be combined with inputRef/element");
            }
            await pw.setInputFilesViaPlaywright({
              cdpUrl,
              targetId: tab.targetId,
              inputRef,
              element,
              paths: resolvedPaths,
            });
          } else {
            await pw.armFileUploadViaPlaywright({
              cdpUrl,
              targetId: tab.targetId,
              paths: resolvedPaths,
              timeoutMs: timeoutMs ?? undefined,
            });
            if (ref) {
              await pw.clickViaPlaywright({
                cdpUrl,
                targetId: tab.targetId,
                ssrfPolicy: ctx.state().resolved.ssrfPolicy,
                ref,
              });
            }
          }
          res.json({ ok: true });
        },
      });
    }),
  );

  app.post(
    "/hooks/dialog",
    asyncBrowserRoute(async (req, res) => {
      const body = readBody(req);
      const targetId = resolveTargetIdFromBody(body);
      const accept = toBoolean(body.accept);
      const promptText = toStringOrEmpty(body.promptText) || undefined;
      let timeoutMs: number | undefined;
      try {
        timeoutMs = readRouteTimerTimeoutMs(body.timeoutMs);
      } catch (err) {
        return jsonError(res, 400, formatErrorMessage(err));
      }
      const dialogId = toStringOrEmpty(body.dialogId) || undefined;
      if (accept === undefined) {
        return jsonError(res, 400, "accept is required");
      }

      await withRouteTabContext({
        req,
        res,
        ctx,
        targetId,
        run: async ({ profileCtx, cdpUrl, tab }) => {
          if (getBrowserProfileCapabilities(profileCtx.profile).usesChromeMcp) {
            if (dialogId) {
              return jsonError(res, 501, EXISTING_SESSION_LIMITS.hooks.dialogId);
            }
            if (timeoutMs) {
              return jsonError(res, 501, EXISTING_SESSION_LIMITS.hooks.dialogTimeout);
            }
            await evaluateChromeMcpScript({
              profileName: profileCtx.profile.name,
              profile: profileCtx.profile,
              targetId: tab.targetId,
              // Existing-session Chrome MCP has no dialog hook primitive. Patch
              // one-shot window dialog functions in-page, then restore them.
              fn: `() => {
              const state = (window.__openclawDialogHook ??= {});
              if (!state.originals) {
                state.originals = {
                  alert: window.alert.bind(window),
                  confirm: window.confirm.bind(window),
                  prompt: window.prompt.bind(window),
                };
              }
              const originals = state.originals;
              const restore = () => {
                window.alert = originals.alert;
                window.confirm = originals.confirm;
                window.prompt = originals.prompt;
                delete window.__openclawDialogHook;
              };
              window.alert = (...args) => {
                try {
                  return undefined;
                } finally {
                  restore();
                }
              };
              window.confirm = (...args) => {
                try {
                  return ${accept ? "true" : "false"};
                } finally {
                  restore();
                }
              };
              window.prompt = (...args) => {
                try {
                  return ${accept ? JSON.stringify(promptText ?? "") : "null"};
                } finally {
                  restore();
                }
              };
              return true;
            }`,
            });
            return res.json({ ok: true });
          }
          const pw = await requirePwAi(res, "dialog hook");
          if (!pw) {
            return;
          }
          await pw.armDialogViaPlaywright({
            cdpUrl,
            targetId: tab.targetId,
            dialogId,
            accept,
            promptText,
            timeoutMs: timeoutMs ?? undefined,
          });
          res.json({ ok: true });
        },
      });
    }),
  );
}

/**
 * Browser agent action route registration and existing-session execution.
 *
 * Dispatches normalized actions to either Playwright-backed OpenClaw browser
 * control or Chrome MCP existing-session operations with navigation guards.
 */
import { sleep } from "openclaw/plugin-sdk/runtime-env";
import { formatErrorMessage } from "../../infra/errors.js";
import {
  clickChromeMcpElement,
  clickChromeMcpCoords,
  closeChromeMcpTab,
  dragChromeMcpElement,
  evaluateChromeMcpScript,
  fillChromeMcpElement,
  fillChromeMcpForm,
  hoverChromeMcpElement,
  pressChromeMcpKey,
  resizeChromeMcpPage,
  type ChromeMcpProfileOptions,
} from "../chrome-mcp.js";
import type { BrowserActRequest } from "../client-actions.types.js";
import { normalizeBrowserEvaluateFunctionSource } from "../evaluate-source.js";
import {
  assertBrowserNavigationResultAllowed,
  type BrowserNavigationPolicyOptions,
  withBrowserNavigationPolicy,
} from "../navigation-guard.js";
import { getBrowserProfileCapabilities } from "../profile-capabilities.js";
import type { BrowserRouteContext } from "../server-context.js";
import { matchBrowserUrlPattern } from "../url-pattern.js";
import { registerBrowserAgentActDownloadRoutes } from "./agent.act.download.js";
import {
  ACT_ERROR_CODES,
  browserEvaluateDisabledMessage,
  jsonActError,
} from "./agent.act.errors.js";
import { registerBrowserAgentActHookRoutes } from "./agent.act.hooks.js";
import { canonicalizeActTargetIds, normalizeActRequest } from "./agent.act.normalize.js";
import { type ActKind, isActKind } from "./agent.act.shared.js";
import {
  readBody,
  requirePwAi,
  resolveTargetIdFromBody,
  resolveSafeRouteTabUrl,
  withRouteTabContext,
  SELECTOR_UNSUPPORTED_MESSAGE,
} from "./agent.shared.js";
import { resolveTargetIdAfterNavigate } from "./agent.snapshot-target.js";
import { EXISTING_SESSION_LIMITS } from "./existing-session-limits.js";
import { readRoutePositiveInteger, readRouteTimerTimeoutMs } from "./route-numeric.js";
import type { BrowserRouteRegistrar } from "./types.js";
import { asyncBrowserRoute, jsonError, toStringOrEmpty } from "./utils.js";

const EXISTING_SESSION_INTERACTION_NAVIGATION_RECHECK_DELAYS_MS = [0, 250, 500] as const;

async function readExistingSessionLocationHref(params: {
  profileName: string;
  profile?: ChromeMcpProfileOptions;
  userDataDir?: string;
  targetId: string;
}): Promise<string> {
  const currentUrl = await evaluateChromeMcpScript({
    profileName: params.profileName,
    profile: params.profile,
    userDataDir: params.userDataDir,
    targetId: params.targetId,
    fn: "() => window.location.href",
  });
  if (typeof currentUrl !== "string") {
    throw new Error("Location probe returned a non-string result");
  }
  const normalizedUrl = currentUrl.trim();
  if (!normalizedUrl) {
    throw new Error("Location probe returned an empty URL");
  }
  return normalizedUrl;
}

async function assertExistingSessionPostInteractionNavigationAllowed(params: {
  profileName: string;
  profile?: ChromeMcpProfileOptions;
  userDataDir?: string;
  targetId: string;
  ssrfPolicy?: BrowserNavigationPolicyOptions["ssrfPolicy"];
  listTabs: () => Promise<Array<{ targetId: string; url: string }>>;
  initialTabTargetIds: ReadonlySet<string>;
}): Promise<void> {
  const ssrfPolicyOpts = withBrowserNavigationPolicy(params.ssrfPolicy);
  if (!ssrfPolicyOpts.ssrfPolicy) {
    return;
  }
  const listTabs = params.listTabs;
  const initialTabTargetIds = params.initialTabTargetIds;

  const assertNewTabsAllowed = async () => {
    const tabs = await listTabs();
    for (const tab of tabs) {
      if (initialTabTargetIds.has(tab.targetId)) {
        continue;
      }
      await assertBrowserNavigationResultAllowed({
        url: tab.url,
        ...ssrfPolicyOpts,
      });
    }
  };

  let lastObservedUrl: string | undefined;
  let sawStableAllowedUrl = false;
  for (const delayMs of EXISTING_SESSION_INTERACTION_NAVIGATION_RECHECK_DELAYS_MS) {
    if (delayMs > 0) {
      await sleep(delayMs);
    }
    let currentUrl: string;
    try {
      currentUrl = await readExistingSessionLocationHref(params);
    } catch {
      sawStableAllowedUrl = false;
      continue;
    }
    await assertBrowserNavigationResultAllowed({
      url: currentUrl,
      ...ssrfPolicyOpts,
    });
    if (currentUrl === lastObservedUrl) {
      sawStableAllowedUrl = true;
    } else {
      sawStableAllowedUrl = false;
    }
    lastObservedUrl = currentUrl;
  }

  if (sawStableAllowedUrl) {
    await assertNewTabsAllowed();
    return;
  }

  // If the loop exhausted without confirming stability but we did observe
  // at least one allowed URL, run a single follow-up probe so a late URL
  // transition that has already settled is not treated as a false failure.
  if (lastObservedUrl) {
    const lastDelay =
      EXISTING_SESSION_INTERACTION_NAVIGATION_RECHECK_DELAYS_MS[
        EXISTING_SESSION_INTERACTION_NAVIGATION_RECHECK_DELAYS_MS.length - 1
      ];
    await sleep(lastDelay);
    try {
      const followUpUrl = await readExistingSessionLocationHref(params);
      await assertBrowserNavigationResultAllowed({
        url: followUpUrl,
        ...ssrfPolicyOpts,
      });
      if (followUpUrl === lastObservedUrl) {
        await assertNewTabsAllowed();
        return;
      }
    } catch {
      // Probe failed — fall through to throw
    }
  }

  throw new Error("Unable to verify stable post-interaction navigation");
}

async function runExistingSessionActionWithNavigationGuard<T>(params: {
  execute: () => Promise<T>;
  guard?: Parameters<typeof assertExistingSessionPostInteractionNavigationAllowed>[0];
}): Promise<T> {
  let actionError: unknown;
  let result: T | undefined;
  try {
    result = await params.execute();
  } catch (error) {
    actionError = error;
  }

  if (params.guard) {
    await assertExistingSessionPostInteractionNavigationAllowed(params.guard);
  }

  if (actionError) {
    throw toLintErrorObject(actionError, "Non-Error thrown");
  }

  return result as T;
}

function buildExistingSessionWaitPredicate(params: {
  text?: string;
  textGone?: string;
  selector?: string;
  loadState?: "load" | "domcontentloaded" | "networkidle";
  fn?: string;
}): string | null {
  const checks: string[] = [];
  if (params.text) {
    checks.push(`Boolean(document.body?.innerText?.includes(${JSON.stringify(params.text)}))`);
  }
  if (params.textGone) {
    checks.push(`!document.body?.innerText?.includes(${JSON.stringify(params.textGone)})`);
  }
  if (params.selector) {
    checks.push(`Boolean(document.querySelector(${JSON.stringify(params.selector)}))`);
  }
  if (params.loadState === "domcontentloaded") {
    checks.push(`document.readyState === "interactive" || document.readyState === "complete"`);
  } else if (params.loadState === "load") {
    checks.push(`document.readyState === "complete"`);
  }
  if (params.fn) {
    checks.push(`Boolean(await (${params.fn})())`);
  }
  if (checks.length === 0) {
    return null;
  }
  return checks.length === 1 ? checks[0] : checks.map((check) => `(${check})`).join(" && ");
}

async function waitForExistingSessionCondition(params: {
  profileName: string;
  profile?: ChromeMcpProfileOptions;
  userDataDir?: string;
  targetId: string;
  timeMs?: number;
  text?: string;
  textGone?: string;
  selector?: string;
  url?: string;
  loadState?: "load" | "domcontentloaded" | "networkidle";
  fn?: string;
  timeoutMs?: number;
}): Promise<void> {
  if (params.timeMs && params.timeMs > 0) {
    await sleep(params.timeMs);
  }
  const predicate = buildExistingSessionWaitPredicate(params);
  if (!predicate && !params.url) {
    return;
  }
  const timeoutMs = Math.max(250, params.timeoutMs ?? 10_000);
  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    let ready = true;
    if (predicate) {
      ready = Boolean(
        await evaluateChromeMcpScript({
          profileName: params.profileName,
          profile: params.profile,
          userDataDir: params.userDataDir,
          targetId: params.targetId,
          fn: `async () => ${predicate}`,
        }),
      );
    }
    if (ready && params.url) {
      const currentUrl = await evaluateChromeMcpScript({
        profileName: params.profileName,
        profile: params.profile,
        userDataDir: params.userDataDir,
        targetId: params.targetId,
        fn: "() => window.location.href",
      });
      ready = typeof currentUrl === "string" && matchBrowserUrlPattern(params.url, currentUrl);
    }
    if (ready) {
      return;
    }
    await sleep(250);
  }
  throw new Error("Timed out waiting for condition");
}

const SELECTOR_ALLOWED_KINDS: ReadonlySet<string> = new Set([
  "batch",
  "click",
  "drag",
  "hover",
  "scrollIntoView",
  "select",
  "type",
  "wait",
]);

function shouldEnforceCurrentUrlForAct(action: BrowserActRequest): boolean {
  // Batch stays guarded because nested actions can read or return page data.
  return action.kind !== "resize" && action.kind !== "close";
}

function getExistingSessionUnsupportedMessage(action: BrowserActRequest): string | null {
  switch (action.kind) {
    case "click":
      if (action.selector) {
        return EXISTING_SESSION_LIMITS.act.clickSelector;
      }
      if (
        (action.button && action.button !== "left") ||
        (Array.isArray(action.modifiers) && action.modifiers.length > 0)
      ) {
        return EXISTING_SESSION_LIMITS.act.clickButtonOrModifiers;
      }
      return null;
    case "clickCoords":
      return null;
    case "type":
      if (action.selector) {
        return EXISTING_SESSION_LIMITS.act.typeSelector;
      }
      if (action.slowly) {
        return EXISTING_SESSION_LIMITS.act.typeSlowly;
      }
      return action.timeoutMs ? EXISTING_SESSION_LIMITS.act.typeTimeout : null;
    case "press":
      return action.delayMs ? EXISTING_SESSION_LIMITS.act.pressDelay : null;
    case "hover":
      if (action.selector) {
        return EXISTING_SESSION_LIMITS.act.hoverSelector;
      }
      return action.timeoutMs ? EXISTING_SESSION_LIMITS.act.hoverTimeout : null;
    case "scrollIntoView":
      if (action.selector) {
        return EXISTING_SESSION_LIMITS.act.scrollSelector;
      }
      return action.timeoutMs ? EXISTING_SESSION_LIMITS.act.scrollTimeout : null;
    case "drag":
      if (action.startSelector || action.endSelector) {
        return EXISTING_SESSION_LIMITS.act.dragSelector;
      }
      return action.timeoutMs ? EXISTING_SESSION_LIMITS.act.dragTimeout : null;
    case "select":
      if (action.selector) {
        return EXISTING_SESSION_LIMITS.act.selectSelector;
      }
      if (action.values.length !== 1) {
        return EXISTING_SESSION_LIMITS.act.selectSingleValue;
      }
      return action.timeoutMs ? EXISTING_SESSION_LIMITS.act.selectTimeout : null;
    case "fill":
      return action.timeoutMs ? EXISTING_SESSION_LIMITS.act.fillTimeout : null;
    case "wait":
      return action.loadState === "networkidle"
        ? EXISTING_SESSION_LIMITS.act.waitNetworkIdle
        : null;
    case "evaluate":
      return action.timeoutMs !== undefined ? EXISTING_SESSION_LIMITS.act.evaluateTimeout : null;
    case "batch":
      return EXISTING_SESSION_LIMITS.act.batch;
    case "resize":
    case "close":
      return null;
  }
  throw new Error("Unsupported browser act kind");
}

/** Register browser action endpoints, including hook and download subroutes. */
export function registerBrowserAgentActRoutes(
  app: BrowserRouteRegistrar,
  ctx: BrowserRouteContext,
) {
  app.post(
    "/act",
    asyncBrowserRoute(async (req, res) => {
      const body = readBody(req);
      const kindRaw = toStringOrEmpty(body.kind);
      if (!isActKind(kindRaw)) {
        return jsonActError(res, 400, ACT_ERROR_CODES.kindRequired, "kind is required");
      }
      const kind: ActKind = kindRaw;
      let action: BrowserActRequest;
      try {
        action = normalizeActRequest(body);
      } catch (err) {
        return jsonActError(res, 400, ACT_ERROR_CODES.invalidRequest, formatErrorMessage(err));
      }
      const targetId = resolveTargetIdFromBody(body);
      if (Object.hasOwn(body, "selector") && !SELECTOR_ALLOWED_KINDS.has(kind)) {
        return jsonActError(
          res,
          400,
          ACT_ERROR_CODES.selectorUnsupported,
          SELECTOR_UNSUPPORTED_MESSAGE,
        );
      }
      const earlyFn = action.kind === "wait" || action.kind === "evaluate" ? action.fn : "";
      if (
        (action.kind === "evaluate" || (action.kind === "wait" && earlyFn)) &&
        !ctx.state().resolved.evaluateEnabled
      ) {
        return jsonActError(
          res,
          403,
          ACT_ERROR_CODES.evaluateDisabled,
          browserEvaluateDisabledMessage(action.kind === "evaluate" ? "evaluate" : "wait"),
        );
      }

      await withRouteTabContext({
        req,
        res,
        ctx,
        targetId,
        enforceCurrentUrlAllowed: shouldEnforceCurrentUrlForAct(action),
        run: async ({ profileCtx, cdpUrl, tab, resolveTabUrl }) => {
          const evaluateEnabled = ctx.state().resolved.evaluateEnabled;
          const ssrfPolicy = ctx.state().resolved.ssrfPolicy;
          const isExistingSession = getBrowserProfileCapabilities(profileCtx.profile).usesChromeMcp;
          const hasNavigationResultPolicy = Boolean(
            withBrowserNavigationPolicy(ssrfPolicy).ssrfPolicy,
          );
          const jsonOk = async (
            extra?: Record<string, unknown>,
            options?: { resolveCurrentTarget?: boolean },
          ) => {
            const shouldResolveCurrentTarget =
              options?.resolveCurrentTarget && (!isExistingSession || hasNavigationResultPolicy);
            const responseTargetId = shouldResolveCurrentTarget
              ? await resolveTargetIdAfterNavigate({
                  oldTargetId: tab.targetId,
                  navigatedUrl: tab.url,
                  listTabs: () => profileCtx.listTabs(),
                })
              : tab.targetId;
            const url =
              responseTargetId === tab.targetId
                ? await resolveTabUrl(tab.url)
                : await resolveSafeRouteTabUrl({
                    ctx,
                    profileCtx,
                    targetId: responseTargetId,
                    fallbackUrl: tab.url,
                  });
            return res.json({
              ok: true,
              targetId: responseTargetId,
              ...(url ? { url } : {}),
              ...extra,
            });
          };
          // Nested batch aliases can differ from the request alias, so prefixes
          // must stay unique across the full tab set before canonicalization.
          const actionTabs =
            action.kind === "batch" && !isExistingSession ? await profileCtx.listTabs() : [tab];
          if (!actionTabs.some((candidate) => candidate.targetId === tab.targetId)) {
            actionTabs.unshift(tab);
          }
          const targetIdError = canonicalizeActTargetIds(action, tab, actionTabs);
          if (targetIdError) {
            return jsonActError(res, 403, ACT_ERROR_CODES.targetIdMismatch, targetIdError);
          }
          const profileName = profileCtx.profile.name;
          if (isExistingSession) {
            const initialTabTargetIds = hasNavigationResultPolicy
              ? new Set((await profileCtx.listTabs()).map((currentTab) => currentTab.targetId))
              : new Set<string>();
            const existingSessionNavigationGuard = {
              profileName,
              profile: profileCtx.profile,
              targetId: tab.targetId,
              ssrfPolicy,
              listTabs: () => profileCtx.listTabs(),
              initialTabTargetIds,
            };
            const unsupportedMessage = getExistingSessionUnsupportedMessage(action);
            if (unsupportedMessage) {
              return jsonActError(
                res,
                501,
                ACT_ERROR_CODES.unsupportedForExistingSession,
                unsupportedMessage,
              );
            }
            switch (action.kind) {
              case "click":
                await runExistingSessionActionWithNavigationGuard({
                  execute: () =>
                    clickChromeMcpElement({
                      profileName,
                      profile: profileCtx.profile,
                      targetId: tab.targetId,
                      uid: action.ref!,
                      doubleClick: action.doubleClick ?? false,
                      timeoutMs: action.timeoutMs,
                      signal: req.signal,
                    }),
                  guard: existingSessionNavigationGuard,
                });
                return await jsonOk(undefined, { resolveCurrentTarget: true });
              case "clickCoords":
                await runExistingSessionActionWithNavigationGuard({
                  execute: () =>
                    clickChromeMcpCoords({
                      profileName,
                      profile: profileCtx.profile,
                      targetId: tab.targetId,
                      x: action.x,
                      y: action.y,
                      doubleClick: action.doubleClick ?? false,
                      button: action.button as "left" | "right" | "middle" | undefined,
                      delayMs: action.delayMs,
                    }),
                  guard: existingSessionNavigationGuard,
                });
                return await jsonOk(undefined, { resolveCurrentTarget: true });
              case "type":
                await runExistingSessionActionWithNavigationGuard({
                  execute: async () => {
                    await fillChromeMcpElement({
                      profileName,
                      profile: profileCtx.profile,
                      targetId: tab.targetId,
                      uid: action.ref!,
                      value: action.text,
                    });
                    if (action.submit) {
                      await pressChromeMcpKey({
                        profileName,
                        profile: profileCtx.profile,
                        targetId: tab.targetId,
                        key: "Enter",
                      });
                    }
                  },
                  guard: existingSessionNavigationGuard,
                });
                return await jsonOk(undefined, { resolveCurrentTarget: true });
              case "press":
                await runExistingSessionActionWithNavigationGuard({
                  execute: () =>
                    pressChromeMcpKey({
                      profileName,
                      profile: profileCtx.profile,
                      targetId: tab.targetId,
                      key: action.key,
                    }),
                  guard: existingSessionNavigationGuard,
                });
                return await jsonOk(undefined, { resolveCurrentTarget: true });
              case "hover":
                await runExistingSessionActionWithNavigationGuard({
                  execute: () =>
                    hoverChromeMcpElement({
                      profileName,
                      profile: profileCtx.profile,
                      targetId: tab.targetId,
                      uid: action.ref!,
                    }),
                  guard: existingSessionNavigationGuard,
                });
                return await jsonOk();
              case "scrollIntoView":
                await runExistingSessionActionWithNavigationGuard({
                  execute: () =>
                    evaluateChromeMcpScript({
                      profileName,
                      profile: profileCtx.profile,
                      targetId: tab.targetId,
                      fn: `(el) => { el.scrollIntoView({ block: "center", inline: "center" }); return true; }`,
                      args: [action.ref!],
                    }),
                  guard: existingSessionNavigationGuard,
                });
                return await jsonOk();
              case "drag":
                await runExistingSessionActionWithNavigationGuard({
                  execute: () =>
                    dragChromeMcpElement({
                      profileName,
                      profile: profileCtx.profile,
                      targetId: tab.targetId,
                      fromUid: action.startRef!,
                      toUid: action.endRef!,
                    }),
                  guard: existingSessionNavigationGuard,
                });
                return await jsonOk();
              case "select":
                await runExistingSessionActionWithNavigationGuard({
                  execute: () =>
                    fillChromeMcpElement({
                      profileName,
                      profile: profileCtx.profile,
                      targetId: tab.targetId,
                      uid: action.ref!,
                      value: action.values[0] ?? "",
                    }),
                  guard: existingSessionNavigationGuard,
                });
                return await jsonOk();
              case "fill":
                await runExistingSessionActionWithNavigationGuard({
                  execute: () =>
                    fillChromeMcpForm({
                      profileName,
                      profile: profileCtx.profile,
                      targetId: tab.targetId,
                      elements: action.fields.map((field) => ({
                        uid: field.ref,
                        value: String(field.value ?? ""),
                      })),
                    }),
                  guard: existingSessionNavigationGuard,
                });
                return await jsonOk();
              case "resize":
                await resizeChromeMcpPage({
                  profileName,
                  profile: profileCtx.profile,
                  targetId: tab.targetId,
                  width: action.width,
                  height: action.height,
                });
                return await jsonOk();
              case "wait":
                await waitForExistingSessionCondition({
                  profileName,
                  profile: profileCtx.profile,
                  targetId: tab.targetId,
                  timeMs: action.timeMs,
                  text: action.text,
                  textGone: action.textGone,
                  selector: action.selector,
                  url: action.url,
                  loadState: action.loadState,
                  fn: action.fn,
                  timeoutMs: action.timeoutMs,
                });
                return await jsonOk();
              case "evaluate": {
                const result = await runExistingSessionActionWithNavigationGuard({
                  execute: () =>
                    evaluateChromeMcpScript({
                      profileName,
                      profile: profileCtx.profile,
                      targetId: tab.targetId,
                      fn: normalizeBrowserEvaluateFunctionSource(
                        action.fn,
                        action.ref ? { argumentName: "el" } : undefined,
                      ),
                      args: action.ref ? [action.ref] : undefined,
                    }),
                  guard: existingSessionNavigationGuard,
                });
                return await jsonOk({ result });
              }
              case "close":
                await closeChromeMcpTab(profileName, tab.targetId, profileCtx.profile);
                return await jsonOk();
              case "batch":
                return jsonActError(
                  res,
                  501,
                  ACT_ERROR_CODES.unsupportedForExistingSession,
                  EXISTING_SESSION_LIMITS.act.batch,
                );
            }
          }

          const pw = await requirePwAi(res, `act:${kind}`);
          if (!pw) {
            return;
          }
          const result = await pw.executeActViaPlaywright({
            cdpUrl,
            action,
            targetId: tab.targetId,
            evaluateEnabled,
            ssrfPolicy,
            signal: req.signal,
          });
          if (result.blockedByDialog) {
            return await jsonOk({
              blockedByDialog: true,
              browserState: result.browserState,
            });
          }
          const downloads = result.downloads;
          switch (action.kind) {
            case "batch":
              return await jsonOk(
                { results: result.results ?? [], ...(downloads ? { downloads } : {}) },
                { resolveCurrentTarget: true },
              );
            case "evaluate":
              return await jsonOk(
                { result: result.result, ...(downloads ? { downloads } : {}) },
                { resolveCurrentTarget: true },
              );
            case "click":
            case "clickCoords":
              return await jsonOk(downloads ? { downloads } : undefined, {
                resolveCurrentTarget: true,
              });
            case "resize":
              return await jsonOk(downloads ? { downloads } : undefined);
            default:
              return await jsonOk(downloads ? { downloads } : undefined, {
                resolveCurrentTarget: true,
              });
          }
        },
      });
    }),
  );

  registerBrowserAgentActHookRoutes(app, ctx);
  registerBrowserAgentActDownloadRoutes(app, ctx);

  app.post(
    "/response/body",
    asyncBrowserRoute(async (req, res) => {
      const body = readBody(req);
      const targetId = resolveTargetIdFromBody(body);
      const url = toStringOrEmpty(body.url);
      let timeoutMs: number | undefined;
      let maxChars: number | undefined;
      try {
        timeoutMs = readRouteTimerTimeoutMs(body.timeoutMs);
        maxChars = readRoutePositiveInteger(body.maxChars, "maxChars");
      } catch (err) {
        return jsonError(res, 400, formatErrorMessage(err));
      }
      if (!url) {
        return jsonError(res, 400, "url is required");
      }

      await withRouteTabContext({
        req,
        res,
        ctx,
        targetId,
        enforceCurrentUrlAllowed: true,
        run: async ({ profileCtx, cdpUrl, tab, resolveTabUrl }) => {
          if (getBrowserProfileCapabilities(profileCtx.profile).usesChromeMcp) {
            return jsonError(res, 501, EXISTING_SESSION_LIMITS.responseBody);
          }
          const pw = await requirePwAi(res, "response body");
          if (!pw) {
            return;
          }
          const result = await pw.responseBodyViaPlaywright({
            cdpUrl,
            targetId: tab.targetId,
            url,
            timeoutMs: timeoutMs ?? undefined,
            maxChars: maxChars ?? undefined,
          });
          const currentUrl = await resolveTabUrl(tab.url);
          res.json({
            ok: true,
            targetId: tab.targetId,
            ...(currentUrl ? { url: currentUrl } : {}),
            response: result,
          });
        },
      });
    }),
  );

  app.post(
    "/highlight",
    asyncBrowserRoute(async (req, res) => {
      const body = readBody(req);
      const targetId = resolveTargetIdFromBody(body);
      const ref = toStringOrEmpty(body.ref);
      if (!ref) {
        return jsonError(res, 400, "ref is required");
      }

      await withRouteTabContext({
        req,
        res,
        ctx,
        targetId,
        enforceCurrentUrlAllowed: true,
        run: async ({ profileCtx, cdpUrl, tab, resolveTabUrl }) => {
          const jsonOk = async () => {
            const currentUrl = await resolveTabUrl(tab.url);
            return res.json({
              ok: true,
              targetId: tab.targetId,
              ...(currentUrl ? { url: currentUrl } : {}),
            });
          };
          if (getBrowserProfileCapabilities(profileCtx.profile).usesChromeMcp) {
            await evaluateChromeMcpScript({
              profileName: profileCtx.profile.name,
              profile: profileCtx.profile,
              targetId: tab.targetId,
              args: [ref],
              fn: `(el) => {
              if (!(el instanceof Element)) {
                return false;
              }
              el.scrollIntoView({ block: "center", inline: "center" });
              const previousOutline = el.style.outline;
              const previousOffset = el.style.outlineOffset;
              el.style.outline = "3px solid #FF4500";
              el.style.outlineOffset = "2px";
              setTimeout(() => {
                el.style.outline = previousOutline;
                el.style.outlineOffset = previousOffset;
              }, 2000);
              return true;
            }`,
            });
            return await jsonOk();
          }
          const pw = await requirePwAi(res, "highlight");
          if (!pw) {
            return;
          }
          await pw.highlightViaPlaywright({
            cdpUrl,
            targetId: tab.targetId,
            ref,
          });
          await jsonOk();
        },
      });
    }),
  );
}

function toLintErrorObject(value: unknown, fallbackMessage: string): Error {
  if (value instanceof Error) {
    return value;
  }
  if (typeof value === "string") {
    return new Error(value);
  }
  const error = new Error(fallbackMessage, { cause: value });
  if ((typeof value === "object" && value !== null) || typeof value === "function") {
    Object.assign(error, value);
  }
  return error;
}

/**
 * Shared browser route helpers.
 *
 * Centralizes body/query parsing, profile resolution, error mapping, Playwright
 * availability checks, and tab-context guards for route modules.
 */
import { normalizeOptionalString } from "openclaw/plugin-sdk/string-coerce-runtime";
import { resolveBrowserNavigationProxyMode } from "../browser-proxy-mode.js";
import { toBrowserErrorResponse } from "../errors.js";
import {
  assertBrowserNavigationResultAllowed,
  withBrowserNavigationPolicy,
} from "../navigation-guard.js";
import type { PwAiModule } from "../pw-ai-module.js";
import { getPwAiModule as getPwAiModuleBase } from "../pw-ai-module.js";
import type { BrowserRouteContext, ProfileContext } from "../server-context.js";
import type { BrowserRequest, BrowserResponse } from "./types.js";
import { getProfileContext, jsonError } from "./utils.js";

export const SELECTOR_UNSUPPORTED_MESSAGE = [
  "Error: 'selector' is not supported. Use 'ref' from snapshot instead.",
  "",
  "Example workflow:",
  "1. snapshot action to get page state with refs",
  '2. act with ref: "e123" to interact with element',
  "",
  "This is more reliable for modern SPAs.",
].join("\n");

/** Return a safe object body for routes that accept JSON payloads. */
export function readBody(req: BrowserRequest): Record<string, unknown> {
  const body = req.body as Record<string, unknown> | undefined;
  if (!body || typeof body !== "object" || Array.isArray(body)) {
    return {};
  }
  return body;
}

/** Read an optional targetId from a request body. */
export function resolveTargetIdFromBody(body: Record<string, unknown>): string | undefined {
  const targetId = normalizeOptionalString(body.targetId) ?? "";
  return targetId || undefined;
}

/** Read an optional targetId from a query object. */
export function resolveTargetIdFromQuery(query: Record<string, unknown>): string | undefined {
  const targetId = normalizeOptionalString(query.targetId) ?? "";
  return targetId || undefined;
}

/** Map route-level browser errors to HTTP JSON responses. */
export function handleRouteError(ctx: BrowserRouteContext, res: BrowserResponse, err: unknown) {
  const mapped = ctx.mapTabError(err);
  if (mapped) {
    return jsonError(res, mapped.status, mapped.message);
  }
  const browserMapped = toBrowserErrorResponse(err);
  if (browserMapped) {
    return jsonError(res, browserMapped.status, browserMapped.message);
  }
  jsonError(res, 500, String(err));
}

/** Resolve the requested browser profile and respond with JSON on failure. */
export function resolveProfileContext(
  req: BrowserRequest,
  res: BrowserResponse,
  ctx: BrowserRouteContext,
): ProfileContext | null {
  const profileCtx = getProfileContext(req, ctx);
  if ("error" in profileCtx) {
    jsonError(res, profileCtx.status, profileCtx.error);
    return null;
  }
  return profileCtx;
}

/** Build navigation guard policy for a profile and current resolved config. */
export function browserNavigationPolicyForProfile(
  ctx: BrowserRouteContext,
  profileCtx: ProfileContext,
) {
  return withBrowserNavigationPolicy(ctx.state().resolved.ssrfPolicy, {
    browserProxyMode: resolveBrowserNavigationProxyMode({
      resolved: ctx.state().resolved,
      profile: profileCtx.profile,
    }),
  });
}

/** Load the optional Playwright bridge module in soft-fail mode. */
export async function getPwAiModule(): Promise<PwAiModule | null> {
  return await getPwAiModuleBase({ mode: "soft" });
}

/** Require Playwright support for a route feature, returning a 501 when absent. */
export async function requirePwAi(
  res: BrowserResponse,
  feature: string,
): Promise<PwAiModule | null> {
  const mod = await getPwAiModule();
  if (mod) {
    return mod;
  }
  jsonError(
    res,
    501,
    [
      `Playwright is not available in this gateway build; '${feature}' is unsupported.`,
      "Reinstall or update OpenClaw so the core browser runtime dependency is present, then restart the gateway. In Docker, also install Chromium with the bundled playwright-core CLI.",
      "Docs: /tools/browser-control#playwright-requirement",
    ].join("\n"),
  );
  return null;
}

type RouteTabContext = {
  profileCtx: ProfileContext;
  tab: Awaited<ReturnType<ProfileContext["ensureTabAvailable"]>>;
  cdpUrl: string;
  resolveTabUrl: (fallbackUrl?: string) => Promise<string | undefined>;
};

type RouteTabPwContext = RouteTabContext & {
  pw: PwAiModule;
};

type RouteWithTabParams<T> = {
  req: BrowserRequest;
  res: BrowserResponse;
  ctx: BrowserRouteContext;
  targetId?: string;
  /**
   * Set for routes that read from or return data scoped to the selected tab.
   * Leave false only for routes that navigate, activate, close, or otherwise manage the tab.
   */
  enforceCurrentUrlAllowed?: boolean;
  run: (ctx: RouteTabContext) => Promise<T>;
};

/** Resolve profile and tab context, optionally enforcing current URL policy. */
export async function withRouteTabContext<T>(
  params: RouteWithTabParams<T>,
): Promise<T | undefined> {
  const profileCtx = resolveProfileContext(params.req, params.res, params.ctx);
  if (!profileCtx) {
    return undefined;
  }
  try {
    // Agent routes can address local-managed tabs through Playwright when per-tab WS discovery lags.
    const tab = await profileCtx.ensureTabAvailable(params.targetId, {
      allowPlaywrightFallback: true,
    });
    if (params.enforceCurrentUrlAllowed) {
      await assertBrowserNavigationResultAllowed({
        url: tab.url,
        ...browserNavigationPolicyForProfile(params.ctx, profileCtx),
      });
    }
    return await params.run({
      profileCtx,
      tab,
      cdpUrl: profileCtx.profile.cdpUrl,
      resolveTabUrl: (fallbackUrl?: string) =>
        resolveSafeRouteTabUrl({
          ctx: params.ctx,
          profileCtx,
          targetId: tab.targetId,
          fallbackUrl,
        }),
    });
  } catch (err) {
    handleRouteError(params.ctx, params.res, err);
    return undefined;
  }
}

/**
 * Response-only URL redaction. This swallows policy failures and must not be used as
 * an execution gate; use enforceCurrentUrlAllowed on the route helper instead.
 */
export async function resolveSafeRouteTabUrl(params: {
  ctx: BrowserRouteContext;
  profileCtx: ProfileContext;
  targetId: string;
  fallbackUrl?: string;
}): Promise<string | undefined> {
  const tabs = await params.profileCtx.listTabs().catch(() => []);
  const candidateUrl =
    tabs.find((tab) => tab.targetId === params.targetId)?.url ?? params.fallbackUrl;
  if (!candidateUrl) {
    return undefined;
  }
  try {
    await assertBrowserNavigationResultAllowed({
      url: candidateUrl,
      ...browserNavigationPolicyForProfile(params.ctx, params.profileCtx),
    });
    return candidateUrl;
  } catch {
    return undefined;
  }
}

type RouteWithPwParams<T> = {
  req: BrowserRequest;
  res: BrowserResponse;
  ctx: BrowserRouteContext;
  targetId?: string;
  feature: string;
  /**
   * Set for routes that read from or return data scoped to the selected tab.
   * Leave false only for routes that navigate, activate, close, or otherwise manage the tab.
   */
  enforceCurrentUrlAllowed?: boolean;
  run: (ctx: RouteTabPwContext) => Promise<T>;
};

/** Resolve profile, tab, and Playwright context for Playwright-only routes. */
export async function withPlaywrightRouteContext<T>(
  params: RouteWithPwParams<T>,
): Promise<T | undefined> {
  return await withRouteTabContext({
    req: params.req,
    res: params.res,
    ctx: params.ctx,
    targetId: params.targetId,
    enforceCurrentUrlAllowed: params.enforceCurrentUrlAllowed,
    run: async ({ profileCtx, tab, cdpUrl, resolveTabUrl }) => {
      const pw = await requirePwAi(params.res, params.feature);
      if (!pw) {
        return undefined as T | undefined;
      }
      return await params.run({ profileCtx, tab, cdpUrl, resolveTabUrl, pw });
    },
  });
}

