  OPEN_TAB_DISCOVERY_POLL_MS,
  OPEN_TAB_DISCOVERY_WINDOW_MS,
} from "./server-context.constants.js";
import type {
  BrowserTab,
  EnsureTabAvailableOptions,
  ProfileRuntimeState,
} from "./server-context.types.js";
import { resolveTargetIdFromTabs } from "./target-id.js";

type SelectionDeps = {
  profile: ResolvedBrowserProfile;
  getProfileState: () => ProfileRuntimeState;
  getCdpControlPolicy: () => SsrFPolicy | undefined;
  ensureBrowserAvailable: (opts?: { headless?: boolean }) => Promise<void>;
  listTabs: () => Promise<BrowserTab[]>;
  openTab: (url: string) => Promise<BrowserTab>;
};

type SelectionOps = {
  ensureTabAvailable: (
    targetId?: string,
    options?: EnsureTabAvailableOptions,
  ) => Promise<BrowserTab>;
  focusTab: (targetId: string) => Promise<void>;
  closeTab: (targetId: string) => Promise<void>;
};

function mergeOpenedTabSnapshot(
  tabs: BrowserTab[],
  openedTab: BrowserTab | undefined,
): BrowserTab[] {
  if (!openedTab) {
    return tabs;
  }
  const index = tabs.findIndex((tab) => tab.targetId === openedTab.targetId);
  if (index < 0) {
    return [...tabs, openedTab];
  }
  const listedTab = tabs[index];
  if (!listedTab || listedTab.wsUrl || !openedTab.wsUrl) {
    return tabs;
  }
  const merged = tabs.slice();
  merged[index] = { ...listedTab, wsUrl: openedTab.wsUrl };
  return merged;
}

function waitForTabDiscoveryPoll(): Promise<void> {
  return new Promise((resolve) => {
    setTimeout(resolve, OPEN_TAB_DISCOVERY_POLL_MS);
  });
}

/** Builds tab selection/focus/close operations for one resolved browser profile. */
export function createProfileSelectionOps({
  profile,
  getProfileState,
  getCdpControlPolicy,
  ensureBrowserAvailable,
  listTabs,
  openTab,
}: SelectionDeps): SelectionOps {
  const cdpHttpBase = normalizeCdpHttpBaseForJsonEndpoints(profile.cdpUrl);
  const capabilities = getBrowserProfileCapabilities(profile);

  const ensureTabAvailable = async (
    targetId?: string,
    options?: EnsureTabAvailableOptions,
  ): Promise<BrowserTab> => {
    await ensureBrowserAvailable();
    const profileState = getProfileState();
    let lastNonEmptyTabs: BrowserTab[] = [];
    let lastListError: unknown;
    let sawSuccessfulList = false;
    let openedTab: BrowserTab | undefined;

    const readTabs = async (): Promise<BrowserTab[]> => {
      try {
        const tabs = await listTabs();
        sawSuccessfulList = true;
        if (tabs.length > 0) {
          lastNonEmptyTabs = tabs;
        }
        return tabs;
      } catch (err) {
        lastListError = err;
        return [];
      }
    };

    const openWhenConfirmedEmpty = async (tabs: BrowserTab[]): Promise<void> => {
      if (!openedTab && sawSuccessfulList && lastNonEmptyTabs.length === 0 && tabs.length === 0) {
        openedTab = await openTab("about:blank");
      }
    };

    const candidateTabs = (tabs: BrowserTab[]) =>
      capabilities.supportsPerTabWs ? tabs.filter((tab) => Boolean(tab.wsUrl)) : tabs;
    const canResolveSelection = (tabs: BrowserTab[]) => {
      const desiredTargetId =
        targetId ??
        openedTab?.targetId ??
        normalizeOptionalString(profileState.lastTargetId) ??
        undefined;
      if (!desiredTargetId) {
        return tabs.length > 0;
      }
      const resolved = resolveTargetIdFromTabs(desiredTargetId, tabs);
      return resolved.ok || resolved.reason === "ambiguous";
    };

    const tabs1 = await readTabs();
    await openWhenConfirmedEmpty(tabs1);

    let listedTabs = await readTabs();
    await openWhenConfirmedEmpty(listedTabs);
    let unfilteredTabs = mergeOpenedTabSnapshot(listedTabs, openedTab);
    let candidates = candidateTabs(unfilteredTabs);
    const preservedCanResolveSelection = () =>
      canResolveSelection(mergeOpenedTabSnapshot(lastNonEmptyTabs, openedTab));

    if (
      capabilities.supportsPerTabWs &&
      !canResolveSelection(candidates) &&
      (candidates.length === 0 ||
        canResolveSelection(unfilteredTabs) ||
        preservedCanResolveSelection())
    ) {
      const deadline = Date.now() + OPEN_TAB_DISCOVERY_WINDOW_MS;
      while (Date.now() < deadline) {
        await waitForTabDiscoveryPoll();
        listedTabs = await readTabs();
        await openWhenConfirmedEmpty(listedTabs);
        unfilteredTabs = mergeOpenedTabSnapshot(listedTabs, openedTab);
        candidates = candidateTabs(unfilteredTabs);
        if (canResolveSelection(candidates)) {
          break;
        }
      }
    }

    if (!canResolveSelection(candidates)) {
      // Keep the last useful discovery snapshot across empty or failed relists.
      // Target-id-only fallback is opt-in because only Playwright-backed callers can use it safely.
      const preservedTabs = mergeOpenedTabSnapshot(lastNonEmptyTabs, openedTab);
      const preservedCandidates = candidateTabs(preservedTabs);
      if (canResolveSelection(preservedCandidates)) {
        candidates = preservedCandidates;
      } else if (options?.allowPlaywrightFallback && canResolveSelection(preservedTabs)) {
        candidates = preservedTabs;
      }
    }

    if (candidates.length === 0 && !sawSuccessfulList && lastListError) {
      throw lastListError instanceof Error
        ? lastListError
        : new Error(formatErrorMessage(lastListError));
    }

    const resolveById = (raw: string) => {
      const resolved = resolveTargetIdFromTabs(raw, candidates);
      if (!resolved.ok) {
        if (resolved.reason === "ambiguous") {
          return "AMBIGUOUS" as const;
        }
        return null;
      }
      return candidates.find((t) => t.targetId === resolved.targetId) ?? null;
    };

    const pickDefault = () => {
      const last = normalizeOptionalString(profileState.lastTargetId) ?? "";
      const lastResolved = last ? resolveById(last) : null;
      if (lastResolved && lastResolved !== "AMBIGUOUS") {
        return lastResolved;
      }
      // Prefer a real page tab first (avoid service workers/background targets).
      const page = candidates.find((t) => (t.type ?? "page") === "page");
      return page ?? candidates.at(0) ?? null;
    };

    const chosen = targetId ? resolveById(targetId) : pickDefault();

    if (chosen === "AMBIGUOUS") {
      throw new BrowserTargetAmbiguousError();
    }
    if (!chosen) {
      throw new BrowserTabNotFoundError(targetId ? { input: targetId } : undefined);
    }
    profileState.lastTargetId = chosen.targetId;
    return chosen;
  };

  const resolveTargetIdOrThrow = async (targetId: string): Promise<string> => {
    const tabs = await listTabs();
    const resolved = resolveTargetIdFromTabs(targetId, tabs);
    if (!resolved.ok) {
      if (resolved.reason === "ambiguous") {
        throw new BrowserTargetAmbiguousError();
      }
      throw new BrowserTabNotFoundError({ input: targetId });
    }
    return resolved.targetId;
  };

  const focusTab = async (targetId: string): Promise<void> => {
    const resolvedTargetId = await resolveTargetIdOrThrow(targetId);

    if (capabilities.usesChromeMcp) {
      const { focusChromeMcpTab } = await getChromeMcpModule();
      await focusChromeMcpTab(profile.name, resolvedTargetId, profile);
      const profileState = getProfileState();
      profileState.lastTargetId = resolvedTargetId;
      return;
    }

    if (capabilities.usesPersistentPlaywright) {
      const mod = await getPwAiModule({ mode: "strict" });
      const focusPageByTargetIdViaPlaywright = (mod as Partial<PwAiModule> | null)
        ?.focusPageByTargetIdViaPlaywright;
      if (typeof focusPageByTargetIdViaPlaywright === "function") {
        await focusPageByTargetIdViaPlaywright({
          cdpUrl: profile.cdpUrl,
          targetId: resolvedTargetId,
          ssrfPolicy: getCdpControlPolicy(),
        });
        const profileState = getProfileState();
        profileState.lastTargetId = resolvedTargetId;
        return;
      }
    }

    await fetchOk(
      appendCdpPath(cdpHttpBase, `/json/activate/${resolvedTargetId}`),
      undefined,
      undefined,
      getCdpControlPolicy(),
    );
    const profileState = getProfileState();
    profileState.lastTargetId = resolvedTargetId;
  };

  const closeTab = async (targetId: string): Promise<void> => {
    const resolvedTargetId = await resolveTargetIdOrThrow(targetId);

    if (capabilities.usesChromeMcp) {
      const { closeChromeMcpTab } = await getChromeMcpModule();
      await closeChromeMcpTab(profile.name, resolvedTargetId, profile);
      return;
    }

    // For remote profiles, use Playwright's persistent connection to close tabs
    if (capabilities.usesPersistentPlaywright) {
      const mod = await getPwAiModule({ mode: "strict" });
      const closePageByTargetIdViaPlaywright = (mod as Partial<PwAiModule> | null)
        ?.closePageByTargetIdViaPlaywright;
      if (typeof closePageByTargetIdViaPlaywright === "function") {
        await closePageByTargetIdViaPlaywright({
          cdpUrl: profile.cdpUrl,
          targetId: resolvedTargetId,
          ssrfPolicy: getCdpControlPolicy(),
        });
        return;
      }
    }

    await fetchOk(
      appendCdpPath(cdpHttpBase, `/json/close/${resolvedTargetId}`),
      undefined,
      undefined,
      getCdpControlPolicy(),
    );
  };

  return {
    ensureTabAvailable,
    focusTab,
    closeTab,
  };
}

/**
 * Browser tab listing, opening, labeling, and alias management for one profile.
 */
import { resolveBrowserNavigationProxyMode } from "./browser-proxy-mode.js";
import { resolveCdpControlPolicy } from "./cdp-reachability-policy.js";
import { isSelectableCdpBrowserTarget } from "./cdp-target-filter.js";
import { CDP_JSON_NEW_TIMEOUT_MS } from "./cdp-timeouts.js";
import {
  assertCdpEndpointAllowed,
  fetchJson,
  fetchOk,
  normalizeCdpHttpBaseForJsonEndpoints,
} from "./cdp.helpers.js";
import { appendCdpPath, createTargetViaCdp, normalizeCdpWsUrl } from "./cdp.js";
import type { CdpActionTimeouts } from "./cdp.js";
import { getChromeMcpModule } from "./chrome-mcp.runtime.js";
import type { ResolvedBrowserProfile } from "./config.js";
import { BrowserTabNotFoundError, BrowserTargetAmbiguousError } from "./errors.js";
import {
  assertBrowserNavigationAllowed,
  assertBrowserNavigationResultAllowed,
  InvalidBrowserNavigationUrlError,
  requiresInspectableBrowserNavigationRedirectsForUrl,
  withBrowserNavigationPolicy,
} from "./navigation-guard.js";
import { getBrowserProfileCapabilities } from "./profile-capabilities.js";
import type { PwAiModule } from "./pw-ai-module.js";
import { getPwAiModule } from "./pw-ai-module.js";
import {
  MANAGED_BROWSER_PAGE_TAB_LIMIT,
  OPEN_TAB_DISCOVERY_POLL_MS,
  OPEN_TAB_DISCOVERY_WINDOW_MS,
} from "./server-context.constants.js";
import type {
  BrowserServerState,
  BrowserTab,
  ProfileRuntimeState,
} from "./server-context.types.js";
import { resolveTargetIdFromTabs } from "./target-id.js";

type TabOpsDeps = {
  profile: ResolvedBrowserProfile;
  state: () => BrowserServerState;
  getProfileState: () => ProfileRuntimeState;
};

type ProfileTabOps = {
  listTabs: () => Promise<BrowserTab[]>;
  openTab: (url: string, opts?: { label?: string }) => Promise<BrowserTab>;
  labelTab: (targetId: string, label: string) => Promise<BrowserTab>;
};

/**
 * Normalize a CDP WebSocket URL to use the correct base URL.
 */
function normalizeWsUrl(raw: string | undefined, cdpBaseUrl: string): string | undefined {
  if (!raw) {
    return undefined;
  }
  try {
    return normalizeCdpWsUrl(raw, cdpBaseUrl);
  } catch {
    return raw;
  }
}

type CdpTarget = {
  id?: string;
  title?: string;
  url?: string;
  webSocketDebuggerUrl?: string;
  type?: string;
};

const TAB_LABEL_PATTERN = /^[A-Za-z0-9_.:-]{1,64}$/;

function normalizeTabLabel(label: string): string {
  const trimmed = label.trim();
  if (!TAB_LABEL_PATTERN.test(trimmed)) {
    throw new Error("tab label must be 1-64 chars and use only letters, numbers, _, ., :, or -");
  }
  return trimmed;
}

function getTabAliasState(
  profileState: ProfileRuntimeState,
): NonNullable<ProfileRuntimeState["tabAliases"]> {
  profileState.tabAliases ??= { nextTabNumber: 1, byTargetId: {} };
  return profileState.tabAliases;
}

function assignTabAlias(params: {
  profileState: ProfileRuntimeState;
  tab: BrowserTab;
  label?: string;
}): BrowserTab {
  const aliases = getTabAliasState(params.profileState);
  let entry = aliases.byTargetId[params.tab.targetId];
  if (!entry) {
    entry = { tabId: `t${aliases.nextTabNumber}` };
    aliases.nextTabNumber += 1;
    aliases.byTargetId[params.tab.targetId] = entry;
  }
  if (params.label) {
    const label = normalizeTabLabel(params.label);
    for (const [targetId, current] of Object.entries(aliases.byTargetId)) {
      if (targetId !== params.tab.targetId && current.label === label) {
        delete current.label;
      }
    }
    entry.label = label;
  }
  entry.url = params.tab.url;
  const labelFields = entry.label ? { label: entry.label } : {};
  return {
    ...params.tab,
    suggestedTargetId: entry.label ?? entry.tabId,
    tabId: entry.tabId,
    ...labelFields,
  };
}

function isConfidentReplacement(params: {
  staleEntry: { url?: string };
  tab: BrowserTab;
  staleCount: number;
  newCandidateCount: number;
}): boolean {
  const staleUrl = params.staleEntry.url?.trim();
  const tabUrl = params.tab.url?.trim();
  if (staleUrl && tabUrl && staleUrl === tabUrl) {
    return true;
  }
  return params.staleCount === 1 && params.newCandidateCount === 1;
}

function assignTabAliases(profileState: ProfileRuntimeState, tabs: BrowserTab[]): BrowserTab[] {
  const aliases = getTabAliasState(profileState);
  const liveTargetIds = new Set(tabs.map((tab) => tab.targetId));
  const staleEntries = Object.entries(aliases.byTargetId).filter(
    ([targetId]) => !liveTargetIds.has(targetId),
  );
  const newCandidates = tabs.filter((tab) => !aliases.byTargetId[tab.targetId]);
  const claimedTargetIds = new Set<string>();

  for (const [oldTargetId, staleEntry] of staleEntries) {
    const candidate = newCandidates.find(
      (tab) =>
        !claimedTargetIds.has(tab.targetId) &&
        isConfidentReplacement({
          staleEntry,
          tab,
          staleCount: staleEntries.length,
          newCandidateCount: newCandidates.length,
        }),
    );
    if (!candidate) {
      continue;
    }
    aliases.byTargetId[candidate.targetId] = staleEntry;
    delete aliases.byTargetId[oldTargetId];
    claimedTargetIds.add(candidate.targetId);
    if (profileState.lastTargetId === oldTargetId) {
      profileState.lastTargetId = candidate.targetId;
    }
  }

  for (const targetId of Object.keys(aliases.byTargetId)) {
    if (!liveTargetIds.has(targetId)) {
      delete aliases.byTargetId[targetId];
    }
  }
  return tabs.map((tab) => assignTabAlias({ profileState, tab }));
}

/** Builds list/open/label tab operations for one resolved browser profile. */
export function createProfileTabOps({
  profile,
  state,
  getProfileState,
}: TabOpsDeps): ProfileTabOps {
  const cdpHttpBase = normalizeCdpHttpBaseForJsonEndpoints(profile.cdpUrl);
  const capabilities = getBrowserProfileCapabilities(profile);
  const getCdpControlPolicy = () => resolveCdpControlPolicy(profile, state().resolved.ssrfPolicy);
  const getNavigationPolicy = () =>
    withBrowserNavigationPolicy(state().resolved.ssrfPolicy, {
      browserProxyMode: resolveBrowserNavigationProxyMode({
        resolved: state().resolved,
        profile,
      }),
    });
  const getRemoteCdpActionTimeouts = (): CdpActionTimeouts | undefined => {
    if (profile.cdpIsLoopback && !profile.attachOnly) {
      return undefined;
    }
    const resolved = state().resolved;
    return {
      httpTimeoutMs: resolved.remoteCdpTimeoutMs,
      handshakeTimeoutMs: resolved.remoteCdpHandshakeTimeoutMs,
    };
  };

  const readTabs = async (): Promise<BrowserTab[]> => {
    if (capabilities.usesChromeMcp) {
      const { listChromeMcpTabs } = await getChromeMcpModule();
      return await listChromeMcpTabs(profile.name, profile);
    }

    if (capabilities.usesPersistentPlaywright) {
      const mod = await getPwAiModule({ mode: "strict" });
      const listPagesViaPlaywright = (mod as Partial<PwAiModule> | null)?.listPagesViaPlaywright;
      if (typeof listPagesViaPlaywright === "function") {
        const ssrfPolicy = getCdpControlPolicy();
        const resolved = state().resolved;
        const timeoutMs = Math.max(
          resolved.remoteCdpTimeoutMs,
          resolved.remoteCdpHandshakeTimeoutMs,
        );
        await assertCdpEndpointAllowed(profile.cdpUrl, ssrfPolicy);
        const pages = await listPagesViaPlaywright({
          cdpUrl: profile.cdpUrl,
          ssrfPolicy,
          timeoutMs,
        });
        return pages.filter(isSelectableCdpBrowserTarget).map((p) => ({
          targetId: p.targetId,
          title: p.title,
          url: p.url,
          type: p.type,
        }));
      }
    }

    const raw = await fetchJson<
      Array<{
        id?: string;
        title?: string;
        url?: string;
        webSocketDebuggerUrl?: string;
        type?: string;
      }>
    >(appendCdpPath(cdpHttpBase, "/json/list"), undefined, undefined, getCdpControlPolicy());
    const cdpControlPolicy = getCdpControlPolicy();
    const tabs: BrowserTab[] = [];
    for (const t of raw) {
      const tab: BrowserTab = {
        targetId: t.id ?? "",
        title: t.title ?? "",
        url: t.url ?? "",
        wsUrl: normalizeWsUrl(t.webSocketDebuggerUrl, profile.cdpUrl),
        type: t.type,
      };
      if (!tab.targetId || !isSelectableCdpBrowserTarget(tab)) {
        continue;
      }
      if (tab.wsUrl) {
        await assertCdpEndpointAllowed(tab.wsUrl, cdpControlPolicy, { source: "discovered" });
      }
      tabs.push(tab);
    }
    return tabs;
  };

  const listTabs = async (): Promise<BrowserTab[]> => {
    const tabs = await readTabs();
    return assignTabAliases(getProfileState(), tabs);
  };

  const enforceManagedTabLimit = async (keepTargetId: string): Promise<void> => {
    const profileState = getProfileState();
    if (
      !capabilities.supportsManagedTabLimit ||
      state().resolved.attachOnly ||
      !profileState.running
    ) {
      return;
    }

    const pageTabs = await listTabs()
      .then((tabs) => tabs.filter((tab) => (tab.type ?? "page") === "page"))
      .catch(() => [] as BrowserTab[]);
    if (pageTabs.length <= MANAGED_BROWSER_PAGE_TAB_LIMIT) {
      return;
    }

    const candidates = pageTabs.filter((tab) => tab.targetId !== keepTargetId);
    const excessCount = pageTabs.length - MANAGED_BROWSER_PAGE_TAB_LIMIT;
    for (const tab of candidates.slice(0, excessCount)) {
      void fetchOk(
        appendCdpPath(cdpHttpBase, `/json/close/${tab.targetId}`),
        undefined,
        undefined,
        getCdpControlPolicy(),
      ).catch(() => {
        // best-effort cleanup only
      });
    }
  };

  const triggerManagedTabLimit = (keepTargetId: string): void => {
    void enforceManagedTabLimit(keepTargetId).catch(() => {
      // best-effort cleanup only
    });
  };

  const openTab = async (url: string, opts?: { label?: string }): Promise<BrowserTab> => {
    const ssrfPolicyOpts = getNavigationPolicy();

    if (capabilities.usesChromeMcp) {
      await assertBrowserNavigationAllowed({ url, ...ssrfPolicyOpts });
      const { openChromeMcpTab } = await getChromeMcpModule();
      const page = await openChromeMcpTab(profile.name, url, profile);
      const profileState = getProfileState();
      profileState.lastTargetId = page.targetId;
      await assertBrowserNavigationResultAllowed({ url: page.url, ...ssrfPolicyOpts });
      return assignTabAlias({ profileState, tab: page, label: opts?.label });
    }

    if (capabilities.usesPersistentPlaywright) {
      const mod = await getPwAiModule({ mode: "strict" });
      const createPageViaPlaywright = (mod as Partial<PwAiModule> | null)?.createPageViaPlaywright;
      if (typeof createPageViaPlaywright === "function") {
        const page = await createPageViaPlaywright({
          cdpUrl: profile.cdpUrl,
          url,
          cdpPolicy: getCdpControlPolicy(),
          ...ssrfPolicyOpts,
        });
        const profileState = getProfileState();
        profileState.lastTargetId = page.targetId;
        triggerManagedTabLimit(page.targetId);
        return assignTabAlias({
          profileState,
          label: opts?.label,
          tab: {
            targetId: page.targetId,
            title: page.title,
            url: page.url,
            type: page.type,
          },
        });
      }
    }

    if (requiresInspectableBrowserNavigationRedirectsForUrl(url, state().resolved.ssrfPolicy)) {
      throw new InvalidBrowserNavigationUrlError(
        "Navigation blocked: strict browser SSRF policy requires Playwright-backed redirect-hop inspection",
      );
    }

    await assertBrowserNavigationAllowed({ url, ...ssrfPolicyOpts });
    const cdpActionTimeouts = getRemoteCdpActionTimeouts();
    const createTargetOpts: Parameters<typeof createTargetViaCdp>[0] = {
      cdpUrl: profile.cdpUrl,
      url,
      ssrfPolicy: getCdpControlPolicy(),
    };
    if (cdpActionTimeouts) {
      createTargetOpts.timeouts = cdpActionTimeouts;
    }
    const createdViaCdp = await createTargetViaCdp(createTargetOpts)
      .then((r) => r.targetId)
      .catch(() => null);

    if (createdViaCdp) {
      const profileState = getProfileState();
      profileState.lastTargetId = createdViaCdp;
      const deadline = Date.now() + OPEN_TAB_DISCOVERY_WINDOW_MS;
      while (Date.now() < deadline) {
        const tabs = await listTabs().catch(() => [] as BrowserTab[]);
        const found = tabs.find((t) => t.targetId === createdViaCdp);
        if (found) {
          await assertBrowserNavigationResultAllowed({ url: found.url, ...ssrfPolicyOpts });
          triggerManagedTabLimit(found.targetId);
          return assignTabAlias({ profileState, tab: found, label: opts?.label });
        }
        await new Promise((r) => {
          setTimeout(r, OPEN_TAB_DISCOVERY_POLL_MS);
        });
      }
      triggerManagedTabLimit(createdViaCdp);
      return assignTabAlias({
        profileState,
        tab: { targetId: createdViaCdp, title: "", url, type: "page" },
        label: opts?.label,
      });
    }

    const encoded = encodeURIComponent(url);
    const endpointUrl = new URL(appendCdpPath(cdpHttpBase, "/json/new"));
    const endpoint = endpointUrl.search
      ? (() => {
          endpointUrl.searchParams.set("url", url);
          return endpointUrl.toString();
        })()
      : `${endpointUrl.toString()}?${encoded}`;
    const created = await fetchJson<CdpTarget>(
      endpoint,
      cdpActionTimeouts?.httpTimeoutMs ?? CDP_JSON_NEW_TIMEOUT_MS,
      {
        method: "PUT",
      },
      getCdpControlPolicy(),
    ).catch(async (err: unknown) => {
      if (String(err).includes("HTTP 405")) {
        return await fetchJson<CdpTarget>(
          endpoint,
          cdpActionTimeouts?.httpTimeoutMs ?? CDP_JSON_NEW_TIMEOUT_MS,
          undefined,
          getCdpControlPolicy(),
        );
      }
      throw err;
    });

    if (!created.id) {
      throw new Error("Failed to open tab (missing id)");
    }
    const profileState = getProfileState();
    profileState.lastTargetId = created.id;
    const resolvedUrl = created.url ?? url;
    await assertBrowserNavigationResultAllowed({ url: resolvedUrl, ...ssrfPolicyOpts });
    const wsUrl = normalizeWsUrl(created.webSocketDebuggerUrl, profile.cdpUrl);
    if (wsUrl) {
      await assertCdpEndpointAllowed(wsUrl, getCdpControlPolicy(), { source: "discovered" });
    }
    triggerManagedTabLimit(created.id);
    return assignTabAlias({
      profileState,
      label: opts?.label,
      tab: {
        targetId: created.id,
        title: created.title ?? "",
        url: resolvedUrl,
        wsUrl,
        type: created.type,
      },
    });
  };

  const labelTab = async (targetId: string, label: string): Promise<BrowserTab> => {
    const normalizedLabel = normalizeTabLabel(label);
    const tabs = await listTabs();
    const resolved = resolveTargetIdFromTabs(targetId, tabs);
    if (!resolved.ok) {
      if (resolved.reason === "ambiguous") {
        throw new BrowserTargetAmbiguousError();
      }
      throw new BrowserTabNotFoundError({ input: targetId });
    }
    const tab = tabs.find((candidate) => candidate.targetId === resolved.targetId);
    if (!tab) {
      throw new BrowserTabNotFoundError({ input: targetId });
    }
    return assignTabAlias({ profileState: getProfileState(), tab, label: normalizedLabel });
  };

  return {
    listTabs,
    openTab,
    labelTab,
  };
}

