    await client.request(rpc.method, rpc.params);
    if (state.client !== client) {
      return;
    }
    state.execApprovalsDirty = false;
    await loadExecApprovals(state, target);
  } catch (err) {
    if (state.client === client) {
      state.lastError = String(err);
