    await buildGatewayInstallPlan({
      env: installEnv,
      port,
      runtime: runtimeRaw,
      wrapperPath,
      existingEnvironment: existingServiceEnv,
      existingEnvironmentValueSources: existingServiceCommand?.environmentValueSources,
      warn: (message) => {
        if (json) {
          warnings.push(message);
